import {validateSnapshot,migrateSnapshot} from './snapshot.js';
// Deliberately a separate database, with one replaceable record and no campaign writer.
function open(){return new Promise((resolve,reject)=>{const r=indexedDB.open('scroll-trainer-viewer',1);r.onupgradeneeded=()=>r.result.createObjectStore('snapshot');r.onerror=()=>reject(Error('Snapshot storage unavailable.'));r.onsuccess=()=>resolve(r.result);});}
export async function loadSnapshot(){const db=await open();try{return await new Promise((resolve,reject)=>{const t=db.transaction('snapshot','readwrite'),r=t.objectStore('snapshot').get('current');let value=null,problem;r.onsuccess=()=>{try{if(r.result){value=migrateSnapshot(r.result);if(value!==r.result)t.objectStore('snapshot').put(value,'current');}}catch(e){problem=e;t.abort();}};t.oncomplete=()=>resolve(value);t.onabort=()=>reject(problem||t.error);});}finally{db.close();}}
export async function replaceSnapshot(p){p=migrateSnapshot(p);const db=await open();try{await new Promise((resolve,reject)=>{const t=db.transaction('snapshot','readwrite');t.objectStore('snapshot').put(p,'current');t.oncomplete=resolve;t.onabort=()=>reject(Error('Snapshot was not saved. Previous snapshot is unchanged.'));});}finally{db.close();}}
